import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/features/purchases/data/purchase_repository.dart';import 'package:pos_app/shared/presentation/database_list_screen.dart';class PurchasesScreen extends StatelessWidget{const PurchasesScreen({super.key});@override Widget build(BuildContext context)=>DatabaseListScreen(title:'Compras',query:'SELECT id,global_id,purchase_date,total_cents,status FROM purchases ORDER BY id DESC',action:(c)async{final v=await textForm(c,'Registrar compra',['Supplier ID','Supplier GID','Product ID','Product GID','Cantidad','Costo centavos']);if(v!=null)await PurchaseRepository(appDatabase).create(supplierId:int.parse(v[0]),supplierGlobalId:v[1],lines:[PurchaseLineInput(int.parse(v[2]),v[3],int.parse(v[4]),int.parse(v[5]))]);});}
